package net.civeira.phylax.features.oauth.userinvitation.domain.gateway;

import java.util.Optional;

/**
 * Accepts an invitation: creates its user and marks it accepted in a single transaction, so an
 * invitation is accepted at most once (task 2.2).
 */
public interface InvitationAcceptGateway {

  /**
   * Accepts a pending, unexpired invitation.
   *
   * @param invitationUid invitation identifier
   * @param password password of the new account
   * @return uid of the created user, empty when the invitation was no longer pending (another
   *         acceptance won) or the account already exists
   */
  Optional<String> acceptAndCreateUser(String invitationUid, String password);
}
